with.code:
const out = $json.output || $json;
const brand = $('Load Brand Config').first().json || {};
const floor = brand.quality_floor ?? 0.7;
const status = out.overall >= floor ? 'pass' : (out.overall >= floor - 0.15 ? 'warn' : 'fail');
return [{ json: { status, score: out.overall, scores: out.scores, violations: out.violations || [], floor, may_proceed: status !== 'fail' } }];
